const stats = $('Get Today's Stats').first().json;
const tasks = $('Get Today\'s Tasks').all().map(t => t.json);
const hotLeads = $('Get Hot Leads Needing Attention').all().map(l => l.json);
const creds = $('Get WhatsApp Credentials').first().json;

const day = new Date().toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long' });

let msg = `🌅 Good Morning, Kamar!\n\n📅 ${day}\n\n`;
msg += `📊 OVERNIGHT SUMMARY:\n`;
msg += `• New leads: ${stats.leads_today || 0}\n`;
msg += `• Hot leads: ${stats.hot_leads || 0}\n`;
msg += `• Converted: ${stats.converted_today || 0}\n`;
msg += `• Revenue: Rs ${parseInt(stats.revenue_today || 0).toLocaleString('en-IN')}\n`;
msg += `• Messages received: ${stats.messages_received || 0}\n\n`;

if (hotLeads.length > 0) {
  msg += `🔥 HOT LEADS NEEDING YOUR ATTENTION:\n`;
  hotLeads.forEach((l, i) => {
    msg += `${i+1}. ${l.name} (${l.brand}) — Score: ${l.score}\n`;
    msg += `   📞 ${l.phone} | ${l.interest}\n`;
  });
  msg += `\n`;
}

if (tasks.length > 0) {
  msg += `✅ TODAY'S TASKS (${tasks.length}):\n`;
  tasks.forEach((t, i) => {
    const p = t.priority === 'high' ? '🔴' : t.priority === 'medium' ? '🟡' : '🟢';
    msg += `${p} ${t.title}\n`;
    if (t.assigned_to) msg += `   → ${t.assigned_to}\n`;
  });
  msg += `\n`;
}

msg += `📱 Dashboard: https://leados-app.abmgroups.org`;

return [{ json: { message: msg, phone_number_id: creds.phone_number_id, wa_access_token: creds.wa_access_token } }];
